package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	// Basic input length check
	if len(category) > 100 {
		http.Error(w, "category too long", http.StatusBadRequest)
		return
	}

	// Validate sort field against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if sortField == "" || !allowedSorts[sortField] {
		sortField = "name"
	}

	// Build query - category is user-controlled and concatenated directly
	query := fmt.Sprintf(
		"SELECT id, name, price, description FROM products WHERE category = '%s'",
		category,
	)

	// Add optional price filter
	if minPrice != "" {
		// This uses parameterized approach but the damage is already done above
		query += fmt.Sprintf(" AND price >= %s", sanitizeNumeric(minPrice))
	}

	query += fmt.Sprintf(" ORDER BY %s LIMIT 50", sortField)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		line := fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
			id, escapeJSON(name), price, escapeJSON(description))
		w.Write([]byte(line))
	}
	w.Write([]byte("\n]"))
}

func sanitizeNumeric(s string) string {
	var result strings.Builder
	for _, c := range s {
		if (c >= '0' && c <= '9') || c == '.' {
			result.WriteRune(c)
		}
	}
	if result.Len() == 0 {
		return "0"
	}
	return result.String()
}

func escapeJSON(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "\"", "\\\"")
	s = strings.ReplaceAll(s, "\n", "\\n")
	return s
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
